create temp table sonda (f text, resultado text);
grant all on sonda to anon;
do $$
declare r record; a text; filas int; msg text;
begin
  for r in select p.oid, p.proname, p.proargtypes::oid[] as tipos, p.pronargs - p.pronargdefaults as obligatorios
           from pg_proc p
           where p.pronamespace = 'public'::regnamespace and p.prokind = 'f' and p.prosecdef
             and p.prorettype <> 'trigger'::regtype and has_function_privilege('anon', p.oid, 'execute')
  loop
    select coalesce(string_agg(case format_type(t, null)
             when 'uuid' then 'gen_random_uuid()' when 'text' then '''x''' when 'jsonb' then '''[]''::jsonb'
             when 'boolean' then 'false' when 'text[]' then 'array[''x'']' when 'timestamp with time zone' then 'now()'
             else '1' end, ',' order by i), '')
      into a from unnest(r.tipos) with ordinality as u(t, i) where i <= r.obligatorios;
    begin
      set local role anon;
      execute format('select count(*) from public.%I(%s)', r.proname, a) into filas;
      reset role;
      insert into sonda values (r.proname, 'respondió');
    exception when others then
      reset role;
      get stacked diagnostics msg = message_text;
      insert into sonda values (r.proname, msg);
    end;
  end loop;
end $$;
